import{_ as n,o as e,c as s,a0 as t}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"LRP / QUIC Relay Transport","description":"","frontmatter":{"title":"LRP / QUIC Relay Transport"},"headers":[],"relativePath":"design/lrp-quic.md","filePath":"design/lrp-quic.md"}'),l={name:"design/lrp-quic.md"};function r(p,a,i,o,c,d){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="lrp-quic-relay-transport" tabindex="-1">LRP / QUIC Relay Transport <a class="header-anchor" href="#lrp-quic-relay-transport" aria-label="Permalink to &quot;LRP / QUIC Relay Transport&quot;">​</a></h1><blockquote><p>Source: <code>superpowers/specs/design-wrrp-quic.md</code></p><p><strong>命名说明</strong>: 代码中已从 WRRP (Wireflow Relay &amp; Routing Protocol) 重命名为 LRP (Lattice Relay Protocol)。本文档保留原始设计内容，仅修正标题。代码文件使用 <code>lrp_</code> 前缀（如 <code>lrp_server.go</code>、<code>lrp_client_quic.go</code>）。</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>LRP (Lattice Relay Protocol, formerly WRRP) is the relay channel used when two peers cannot establish a direct ICE path. The original implementation tunnels WireGuard packets over a persistent HTTP-upgraded TCP connection.</p><h3 id="problems-with-tcp-relay" tabindex="-1">Problems with TCP relay <a class="header-anchor" href="#problems-with-tcp-relay" aria-label="Permalink to &quot;Problems with TCP relay&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Impact</th></tr></thead><tbody><tr><td>Head-of-Line blocking</td><td>A dropped TCP segment stalls all peers on the same connection</td></tr><tr><td>Application-level keepalive</td><td>Custom Ping/Pong logic required</td></tr><tr><td>Slow reconnect</td><td>TCP + HTTP handshake on every reconnect</td></tr><tr><td>No packet-boundary preservation</td><td>Framing layer required on top of TCP stream</td></tr></tbody></table><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ol><li>Eliminate HoL blocking between peer pairs sharing a relay connection</li><li>Simplify keepalive — delegate to QUIC&#39;s built-in mechanism</li><li>Faster reconnect — QUIC 0-RTT resumption</li><li>Preserve packet boundaries — QUIC datagrams map 1:1 to WireGuard packets</li><li>Backward compatibility — TCP relay path remains fully operational; QUIC is opt-in</li></ol><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    LRP Relay Server                     │</span></span>
<span class="line"><span>│                                                          │</span></span>
<span class="line"><span>│  ┌─────────────────────┐   ┌─────────────────────────┐  │</span></span>
<span class="line"><span>│  │   TCP Server        │   │   QUIC Server           │  │</span></span>
<span class="line"><span>│  │   :6266 (HTTP upg.) │   │   :6267 (UDP)           │  │</span></span>
<span class="line"><span>│  └────────┬────────────┘   └──────────┬──────────────┘  │</span></span>
<span class="line"><span>│           └──────────┐   ┌────────────┘                  │</span></span>
<span class="line"><span>│                      ▼   ▼                               │</span></span>
<span class="line"><span>│               ┌─────────────────┐                        │</span></span>
<span class="line"><span>│               │  LRPManager    │                        │</span></span>
<span class="line"><span>│               │  streams map    │  ← TCP sessions        │</span></span>
<span class="line"><span>│               │  quicConns map  │  ← QUIC sessions       │</span></span>
<span class="line"><span>│               └────────┬────────┘                        │</span></span>
<span class="line"><span>│                        │ Relay(toID, frame)              │</span></span>
<span class="line"><span>│                        │  • QUIC: SendDatagram           │</span></span>
<span class="line"><span>│                        │  • TCP:  Stream.Write           │</span></span>
<span class="line"><span>└────────────────────────┼─────────────────────────────────┘</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>         ┌───────────────┴───────────────┐</span></span>
<span class="line"><span>         ▼                               ▼</span></span>
<span class="line"><span>  ┌─────────────┐                 ┌─────────────┐</span></span>
<span class="line"><span>  │  Agent A    │                 │  Agent B    │</span></span>
<span class="line"><span>  │  QUIC client│                 │  QUIC client│</span></span>
<span class="line"><span>  └─────────────┘                 └─────────────┘</span></span></code></pre></div><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li><strong>P2P QUIC between peers</strong> — QUIC cannot replace ICE for NAT traversal. ICE handles hole-punching; QUIC cannot.</li><li><strong>TLS PKI</strong> — Relay server uses a self-signed certificate at startup. Clients use <code>InsecureSkipVerify</code>. Underlying WireGuard encryption provides end-to-end security.</li></ul>`,12)])])}const g=n(l,[["render",r]]);export{u as __pageData,g as default};
